import{z as A,x as s,o as t,c as d,q as i,j as B,D as o,d as E,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"Kiyotaki–Moore 信贷周期","description":"","frontmatter":{"title":"Kiyotaki–Moore 信贷周期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/kiyotaki-moore.md","filePath":"econ/kiyotaki-moore.md","lastUpdated":1791413859000}'),p={name:"econ/kiyotaki-moore.md"};function m(k,a,D,h,u,C){const r=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="kiyotaki–moore-信贷周期" tabindex="-1">Kiyotaki–Moore 信贷周期 <a class="header-anchor" href="#kiyotaki–moore-信贷周期" aria-label="Permalink to &quot;Kiyotaki–Moore 信贷周期&quot;">​</a></h1><div class="epigraph"><p>土地既生产又做抵押；价格下跌收紧约束，强迫出售再压价格——信贷周期是净值的动态，不是外生的贷款意愿残差。</p><footer>—— Kiyotaki and Moore, Credit Cycles, JPE 1997</footer></div><p><a href="/econ/bounded-rationality-nk">上一课</a>把预期摩擦收到 NK。本单元换约束对象：信贷与净值。家庭杠杆课已有经验；本课缺口是 <strong>KM 的一般均衡抵押</strong>：耐用品价格与借贷上限联立。不重写认知折扣，不写限价簿上的保证金微观结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完全市场或无约束的 \\(q\\) 理论：净值不限制投资。KM：可执行的债务受土地未来价值约束。冲击使土地价格 \\(q\\) 降，净值降，信贷降，土地需求降，\\(q\\) 再降。持续性强于冲击本身。缺口是给「金融加速器」一条最干净的抵押装置，而不是先上银行。</p><p><span class="marginnote">Kiyotaki and Moore, <em>JPE</em> 105(2), 1997, 211–248。Bernanke and Gertler 的净值加速器是姐妹，渠道是外部融资溢价而非硬抵押上限。Kocherlakota 对放大的定量提醒。</span></p><p><span class="marginnote">抵押约束翻译成大白话：你能借多少，不取决于你「想借多少」，而取决于抵押品明天值多少，即 \\(b&#39;\\le\\theta q&#39;k&#39;\\)。可以想象成银行只肯借「房子估值打个折」的金额——房价一跌，贷款额度立刻缩水，跟你的还款意愿毫无关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两类人：有生产力的借款人、无生产力的储蓄人。土地供给固定。债务 \\(b&#39;\\le \\theta q&#39; k&#39;\\)。均衡 \\(q\\) 由借款人的土地需求（受约束）与储蓄人的资产需求决定。线性化或完全非线性都可以讲放大。与家庭住房：结构同构，对象换成房。与企业 lumpy：抵押是额外约束，不是固定成本。</p>',9)),(t(),B(l,null,{default:o(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E5%86%B2%E5%87%BB%22%5D%20--%3E%20Q%5B%22%E8%B5%84%E4%BA%A7%E4%BB%B7%E6%A0%BC%20q%22%5D%0A%20%20Q%20--%3E%20NW%5B%22%E5%87%80%E5%80%BC%22%5D%0A%20%20NW%20--%3E%20BOR%5B%22%E6%8A%B5%E6%8A%BC%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20BOR%20--%3E%20DEM%5B%22%E8%B5%84%E4%BA%A7%E9%9C%80%E6%B1%82%22%5D%0A%20%20DEM%20--%3E%20Q%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"政策：放松 \\(\\theta\\)（宏观审慎的反面）可暂时抬 \\(q\\)，埋下更大杠杆——后课审慎。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：取 \\(\\theta=0.6\\)、土地估值 100，借款上限是 60；\\(q\\) 跌两成到 80 后，上限立刻掉到 \\(0.6\\times 80=48\\)。价格只动两成，信贷却收缩 20%，被迫卖地的那 12 正是继续压低 \\(q\\) 的燃料——放大就是这么算出来的。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是价格进入约束。没有这一点，净值只是分配。有这一点，分配改价格再改约束，循环。火线出售：受约束者是边际买家，他们的强迫供给弹性极大。储蓄人若也有限风险承受，吸收能力有限，放大更强——Brunnermeier–Pedersen 的流动性螺旋是同一逻辑的连续时间与保证金版，本课先钉离散 KM。",-1)),(t(),B(l,null,{default:o(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIND%5B%22%E6%8A%B5%E6%8A%BC%E7%BA%A6%E6%9D%9F%E7%BB%91%E5%AE%9A%22%5D%20--%3E%20FORCED%5B%22%E5%80%9F%E6%AC%BE%E4%BA%BA%E8%A2%AB%E8%BF%AB%E7%81%AB%E7%BA%BF%E5%87%BA%E5%94%AE%22%5D%0A%20%20FORCED%20--%3E%20ABS%5B%22%E5%82%A8%E8%93%84%E4%BA%BA%E5%90%B8%E6%94%B6%E5%8D%96%E7%9B%98%22%5D%0A%20%20ABS%20--%3E%20MILD%5B%22q%20%E7%BC%93%E8%B7%8C%3A%20%E6%94%BE%E5%A4%A7%E6%B8%A9%E5%92%8C%22%5D%0A%20%20SAVLIM%5B%22%E5%82%A8%E8%93%84%E4%BA%BA%E9%A3%8E%E9%99%A9%E6%89%BF%E5%8F%97%E6%9C%89%E9%99%90%22%5D%20--%3E%20FAIL%5B%22%E5%90%B8%E6%94%B6%E8%83%BD%E5%8A%9B%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20FAIL%20--%3E%20CRASH%5B%22q%20%E6%80%A5%E8%B7%8C%3A%20%E6%94%BE%E5%A4%A7%E6%9B%B4%E5%BC%BA%22%5D%0A%20%20CRASH%20--%3E%20TIGHT%5B%22%E6%8A%B5%E6%8A%BC%E4%B8%8A%E9%99%90%E6%9B%B4%E7%B4%A7%3A%20%E8%9E%BA%E6%97%8B%E8%87%AA%E6%88%91%E5%8A%A0%E6%B7%B1%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>一阶 DSGE 若把约束「平均掉」，周期里最紧的时候看不见。偶尔绑定要用非线性。</p><p><span class="marginnote">常见误区：以为把约束「取平均」还能看见周期。抵押约束是偶尔才绑定的——大多数时期松弛、危机时才绷紧，取平均之后约束几乎「消失」。要看见 KM 的放大，必须用允许偶尔绑定的非线性方法，这一步做错了，模型的危机动态就整段不见了。</span></p><p><span class="marginnote">本课不把 KM 写成交易策略。也不估计股票横截面的抵押因子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课没有银行（下一课 GK）。没有名义债与通缩（债务通缩课）。定量上纯 KM 的放大可能不够大衰退，需要杠杆初始值、住房、或银行。预期若诊断性过冲，\\(q\\) 的循环更猛，可叠加。</p><p>后课默认：抵押约束把资产价格焊进信贷供给。下一课：中介自己也受约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KM：抵押品价格与信贷上限正反馈，形成信贷周期。</li><li>净值成为状态；放大依赖谁是边际买家。</li><li>银行尚未出现。</li><li>出处：Kiyotaki and Moore, <em>JPE</em> 1997。</li></ul>',8))])}const f=A(p,[["render",m]]);export{q as __pageData,f as default};
